exercise.solution:
tajni = 7
pokusaji = 0

# Petlja while True: učitaj pokušaj, uvećaj brojač, uporedi.
while True:
    pokusaj = int(input("Pogodi broj: "))
    pokusaji += 1
    if pokusaj < tajni:
        print("Veće")
    elif pokusaj > tajni:
        print("Manje")
    else:
        print(f"Pogodio si iz {pokusaji}. pokušaja!")
        break

